const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = readInt();
    if (n === null) return;
    const k = readInt();

    const freq = new Map();
    freq.set(0, 1);

    let currentSum = 0;
    let ans = 0n;

    for (let i = 0; i < n; i++) {
        const x = readInt();
        currentSum += x;
        const target = currentSum - k;
        if (target >= 0) {
            const count = freq.get(target);
            if (count !== undefined) {
                ans += BigInt(count);
            }
        }
        freq.set(currentSum, (freq.get(currentSum) || 0) + 1);
    }

    console.log(ans.toString());
}

solve();
